package config_test

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// CLIResult captures command execution results. Essential for verification.
type CLIResult struct {
	ExitCode int
	Stdout   string
	Stderr   string
}

func runCLI(t *testing.T, args ...string) CLIResult {
	t.Helper()
	cmd := exec.Command("config", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	err := cmd.Run()
	exitCode := 0
	if exitErr, ok := err.(*exec.ExitError); ok {
		exitCode = exitErr.ExitCode()
	}

	return CLIResult{
		ExitCode: exitCode,
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
	}
}

// Test argument parsing. Valid combinations. Invalid permutations.
func TestArgumentParsing(t *testing.T) {
	tests := []struct {
		name         string
		args         []string
		wantExitCode int
		wantInStderr string
	}{
		{"no args shows help", []string{}, 2, "usage"},
		{"unknown command", []string{"unknown"}, 2, "unknown command"},
		{"get without key", []string{"get"}, 2, "requires key"},
		{"set without value", []string{"set", "key"}, 2, "requires value"},
		{"valid get", []string{"get", "database.host"}, 0, ""},
		{"valid set", []string{"set", "key", "value"}, 0, ""},
		{"delete without key", []string{"delete"}, 2, "requires key"},
		{"invalid flag", []string{"--invalid"}, 2, "unknown flag"},
		{"format flag valid", []string{"list", "--format", "json"}, 0, ""},
		{"format flag invalid", []string{"list", "--format", "xml"}, 2, "invalid format"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCLI(t, tt.args...)
			if result.ExitCode != tt.wantExitCode {
				t.Errorf("exit code = %d, want %d", result.ExitCode, tt.wantExitCode)
			}
			if tt.wantInStderr != "" && !bytes.Contains([]byte(result.Stderr), []byte(tt.wantInStderr)) {
				t.Errorf("stderr missing %q", tt.wantInStderr)
			}
		})
	}
}

// Exit codes. Critical for scripting. Automation. CI pipelines.
func TestExitCodes(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantCode int
	}{
		{"success returns 0", []string{"list"}, 0},
		{"runtime error returns 1", []string{"get", "nonexistent", "--config", "/nonexistent"}, 1},
		{"usage error returns 2", []string{"invalid"}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCLI(t, tt.args...)
			if result.ExitCode != tt.wantCode {
				t.Errorf("got %d, want %d", result.ExitCode, tt.wantCode)
			}
		})
	}
}

// Output streams. Data to stdout. Errors to stderr. Non-negotiable.
func TestOutputStreams(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(configPath, []byte("key: value\n"), 0644)

	t.Run("get outputs value to stdout", func(t *testing.T) {
		result := runCLI(t, "get", "key", "--config", configPath)
		if result.Stdout == "" {
			t.Error("expected stdout output")
		}
		if result.Stderr != "" {
			t.Error("unexpected stderr output")
		}
	})

	t.Run("errors go to stderr", func(t *testing.T) {
		result := runCLI(t, "get", "key", "--config", "/nonexistent")
		if result.Stderr == "" {
			t.Error("expected stderr output")
		}
	})

	t.Run("quiet suppresses non-essential", func(t *testing.T) {
		result := runCLI(t, "set", "newkey", "newval", "--config", configPath, "--quiet")
		if result.Stdout != "" {
			t.Error("quiet mode should suppress stdout")
		}
	})
}

// File system operations. Permissions. Creation. Modification.
func TestFileOperations(t *testing.T) {
	t.Run("init creates config file", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "new", "config.yaml")

		result := runCLI(t, "init", "--config", configPath)
		if result.ExitCode != 0 {
			t.Fatalf("init failed: %s", result.Stderr)
		}

		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("read-only file returns error", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "config.yaml")
		os.WriteFile(configPath, []byte("key: value\n"), 0444)

		result := runCLI(t, "set", "key", "newvalue", "--config", configPath)
		if result.ExitCode != 1 {
			t.Error("expected error for read-only file")
		}
	})
}

// Edge cases. Invalid YAML. Missing files. Concurrent access implications.
func TestEdgeCases(t *testing.T) {
	t.Run("invalid YAML syntax", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "config.yaml")
		os.WriteFile(configPath, []byte("invalid: yaml: content:\n  - broken"), 0644)

		result := runCLI(t, "validate", "--config", configPath)
		if result.ExitCode != 1 {
			t.Error("expected validation failure")
		}
		if result.Stderr == "" {
			t.Error("expected error message")
		}
	})

	t.Run("missing config file on get", func(t *testing.T) {
		result := runCLI(t, "get", "key", "--config", "/definitely/not/exists")
		if result.ExitCode != 1 {
			t.Error("expected error for missing file")
		}
	})

	t.Run("empty key rejected", func(t *testing.T) {
		result := runCLI(t, "get", "")
		if result.ExitCode != 2 {
			t.Error("empty key should be usage error")
		}
	})
}
